#!/usr/bin/env python3
"""Render the preserved raw evidence, without inventing missing measurements."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
DATA = ROOT.parent / "reports" / "data" / "metrics-payload-2026-10-09"
REPORT = DATA.parent.parent / "metrics-payload-2026-10-09.md"


def rows(name):
    return [json.loads(line) for line in (DATA / name).read_text().splitlines() if line]


def owned(inspect, name, field="bytes"):
    return sum(o[field] for o in inspect["physical"]["objects"] if o["name"] == name)


def main():
    density = rows("density.jsonl")
    timings = json.loads((DATA / "summary.json").read_text())
    diagnostics = rows("diagnostics.jsonl")
    lifecycle = rows("lifecycle.jsonl")
    verification = rows("verification.jsonl")
    byte_checks = rows("verification-bytes.jsonl")
    env = json.loads((DATA / "environment-performance.json").read_text())
    variants = sorted({r["variant"] for r in timings if r["variant"] != "baseline"})
    def size(dataset,variant):
        return next(r for r in density if r["dataset"]==dataset and r["variant"]==variant)
    def timing(dataset,variant,mode,case,cache):
        return next(r for r in timings if (r["dataset"],r["variant"],r["mode"],r["case"],r["cache"])==(dataset,variant,mode,case,cache))
    def diagnostic(dataset,variant,mode,case,cache):
        return next(r for r in diagnostics if (r["dataset"],r["variant"],r["mode"],r["case"],r["cache"])==(dataset,variant,mode,case,cache))["counters"]
    out = ["# Immutable metrics payload packs and incremental BLOB reads — 2026-10-09", "", "This exploratory round preserves the current production value bodies, shared clocks and version-4 exact-summary contents while changing external-body placement. It tests bounded immutable packs, charged compact addresses, whole-BLOB materialization and safe incremental BLOB access. Production TinyStore is unchanged. These are sealed payload query paths, not an end-to-end public API comparison.", "", "| Question | Answer | What follows |", "| --- | --- | --- |"]
    for dataset in ["tsbs","alibaba"]:
        base=size(dataset,"baseline")["inspect"]["file_bytes"]
        best=min((r for r in density if r["dataset"]==dataset and ("count" in r["variant"] or "bytes" in r["variant"])),key=lambda r:r["inspect"]["file_bytes"])
        current=best["inspect"]["file_bytes"]
        plain=size(dataset,"rowid-baseline")["inspect"]["file_bytes"] if best['variant'].startswith('rowid-') else base
        label="rowid groups without packs" if best['variant'].startswith('rowid-') else "fresh original layout"
        out.append(f"| Best tested packed layout for {dataset}? | `{best['variant']}`: {current:,} bytes; {100*(current/base-1):+.2f}% versus fresh original {base:,}. | Versus {label} ({plain:,} bytes): {100*(current/plain-1):+.2f}%; row-layout gains are separate. |")
    out += ["| Does constant range-copy size prove selective physical I/O? | No. SQLite-cache misses and separate syscall diagnostics measure different work. | Cold here means the SQLite cache, with Linux page cache left alone. |", "| Does retention recover every dead body immediately? | No. A pack remains until its last reference dies. | Retained dead bodies, refcounts, freelist and WAL are recorded separately. |", "", "## Format, baseline and invariant checks", "", "TinyStore source is `e307c48a40126aad0e2873b6bf3aaedef8115483`. The original engine has 32-slot groups, blocks of at most 240 samples, compressed binary v4 directories with exact summaries, a WITHOUT ROWID groups table, shared clocks, inline bodies at most 16 bytes, and separately checked ROWID payload bodies. The fresh native control recreates the original DDL and inserts identical values. Registry, postings, mutable heads and state stay byte-identical in every candidate and remain charged in whole-file totals.", "", "The `0x50/1` experimental directory envelope keeps the original v4 directory, then unique pack rowids and per-external-slot pack-index/offset/expected-CRC references. Its checksum binds the series and group bounds. There is no mapping row per block. Keeping the now-unused original payload-id bytes is conservative and charged. Each pack row also charges reference/live-byte counters and a checked 24-byte identity/length header. Packs never exceed 16 KiB or 32 bodies; each selected block keeps its original body/clock checksum and original decode bound. Byte targets permit one oversized individual body while preserving the 16 KiB hard cap.", "", f"All {len(byte_checks)} density variants pass exhaustive whole/range encoded-body, clock and exact-summary replay. {len(verification)} additional full decoded replays match independently generated production-Go public read hashes and exact-summary byte hashes. Sixteen Rust tests pass, including selected-body corruption, metadata/address bounds, swapped address checks, immutable-address directory replacement, exact float edge cases, and a WAL reader surviving a concurrent writer's pack deletion. The reader closes its Blob and snapshot before decoding owned copied bytes. The inherited test requiring five historical fixture directories is excluded; this round's actual Go fixtures are checked explicitly.", "", "The query paths fetch group/clock metadata, retrieve selected bodies in one snapshot, close all handles and end the snapshot, then decode or fold exact sum/count. Whole-body and whole-pack SQL use batched `json_each` joins. Incremental mode includes safe rusqlite Blob open/read/reopen/close costs. Explicit limits cover directory bytes, requested and copied external bytes, a five-second snapshot, and 100,000 decoded samples. Full-query registry matching, head retrieval, admission, cancellation and concurrent production reader pooling are outside the timings.", "", "## Fresh whole-file density", "", "Every file below is checkpointed, closed and has zero freelist pages after a fresh complete rebuild. System SQLite's read-only `dbstat` scan is outside all timings; the measured archive is not rebuilt with extra instrumentation. Original Go files are reported separately so insertion order/compaction cannot be credited to packs.", ""]
    for dataset in ["tsbs","alibaba","regular","irregular","nonsparse","edge"]:
        manifest=json.loads((DATA/f"{dataset}-manifest.json").read_text())
        original=json.loads((DATA/f"{dataset}-original.json").read_text())
        total=manifest["sample_count"]
        out += [f"### {dataset}: {total:,} samples", "", f"Original Go file: {original['file_bytes']:,} bytes ({original['file_bytes']/total:.6f} bytes/sample). Its physical object census is retained in `{dataset}-original.json`.", "", "| Layout | File bytes | Bytes/sample | Groups b-tree | Payload b-tree | Stored directories | Added directory bytes | Overflow pages |", "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |"]
        base=size(dataset,"baseline")["inspect"]
        for row in (r for r in density if r["dataset"]==dataset):
            s=row["inspect"]; payload=owned(s,"payloads")+owned(s,"payload_packs")
            overflow=sum(o["pages"]for o in s["physical"]["objects"]if o["pagetype"]=="overflow")
            out.append(f"| {row['variant']} | {s['file_bytes']:,} | {s['file_bytes']/total:.6f} | {owned(s,'groups'):,} | {payload:,} | {s['directory_bytes']:,} | {s['directory_bytes']-base['directory_bytes']:+,} | {overflow:,} |")
        out.append("")
    out += ["Each raw density record also contains every object's leaf/internal/overflow pages, cell payload, unused bytes and maximum cell payload. Pack references and row headers are included in groups/payload b-trees, not hidden in an uncounted map. Any existing groups WITHOUT ROWID overflow waste remains charged and is not a packing saving.", "", "## Six balanced performance passes", "", "Numbers below are median microseconds per synchronous backend operation. Point returns one value after decoding its complete block. Sparse reads select 16 blocks across the fixture; range selects up to eight adjacent blocks in one series; full reads the selected series' complete sealed range within the query ceiling; summary folds whole-block exact sums and counts without fetching any value pack. Identical selections and result digests are checked across every implementation and pass.", "", "Each cell uses one common fixed iteration count across candidates. A separate 16-operation pilot targets at least 150 ms for its fastest implementation and caps the slowest projected interval at one second. Counts and projections are in `plan.json`. Six passes reverse candidate order, keeping comparisons for one workload/cache adjacent. Eight warm operations precede each process. Raw timing does not include db-status/VFS/strace instrumentation.", "", "Warm means a warmed 1 MiB SQLite cache. Cold uses `PRAGMA shrink_memory` outside each timed interval; prepared statements stay cached and Linux page cache is not evicted. This shared WSL2 VM does not establish bare-Linux request latency or cold physical disk throughput.", ""]
    out += ["## Compact format and independent row-layout controls", "",
        "Format 0x51 replaces obsolete payload ids inside one compressed directory stream, copying the original scalar/exact-summary and inline tokens verbatim. Compact-unpacked is a same-format control with offset zero and original payload rows; compact-count1 separately charges a pack header/row per body. ROWID-group variants retain and charge their composite UNIQUE index. Group size32 and inline16 stay fixed in this study.", "",
        "The first format0x50 was preserved as executed source under format50-source, with its original environment-density.json. Format0x51 has separate environment-density-format51.json and the later performance environment. All corpora/databases/binaries stay outside Git. This refinement adds no production format reader or migration.", "",
        "Alibaba's best packed combined layout must also be compared with rowid-baseline: the simpler unpacked ROWID groups are smaller. Its apparent saving against original WITHOUT ROWID groups is chiefly a row-layout effect, not a packing gain. TSBS compact-count8 saves only about0.55% against the fresh original control; the nonsparse fixture has a much larger genuine pack gain. The companion group study has a different fresh insertion control and its percentages are not multiplied into these results.", "",
        "Four expected-CRC bytes per external reference are charged explicitly. A dedicated test constructs intact different bodies with equal head and clock; each passes its own original checksum, while the expected trailer rejects an address swap. Removing that field would weaken the tested address-integrity contract, not eliminate an inherent SQLite tax.", "",
        "The compact control changes directory representation, so original v4 directory byte identity is not claimed for0x51. Immutable encoded value bodies, clock residuals, exact-summary encodings and every sample bit remain checked.", ""]
    columns=[("baseline","whole")]+sorted({(r["variant"],r["mode"]) for r in timings if r["variant"]!="baseline"})
    for dataset in ["tsbs","alibaba"]:
        out += [f"### {dataset}", "", "| Query / cache | "+" | ".join(f"{v}/{m}"for v,m in columns)+" |", "| --- | "+" | ".join("---:"for _ in columns)+" |"]
        for case in ["point","sparse","range","full","summary"]:
            for cache in ["warm","cold"]:
                out.append(f"| {case} / {cache} | "+" | ".join(f"{timing(dataset,v,m,case,cache)['median_ns']/1000:.2f}"for v,m in columns)+" |")
        out += ["", "Representative raw passes, microseconds; columns retain the six values instead of hiding spread:", "", "| Query/cache | Implementation | Six passes | Iterations/pass |", "| --- | --- | --- | ---: |"]
        for case in ["point","full"]:
            for cache in ["warm","cold"]:
                for v,m in columns:
                    t=timing(dataset,v,m,case,cache)
                    out.append(f"| {case}/{cache} | {v}/{m} | "+"; ".join(f"{x/1000:.2f}"for x in t["passes_ns"])+f" | {t['iterations']} |")
        out.append("")
    out += ["## Copies, page-cache work and overflow", "", "These counters come from separate untimed diagnostics. `copied` is bytes returned by SQLite's BLOB APIs; whole-pack mode additionally copies selected body slices, reported separately. Requested bytes exclude inline values already present in metadata. Cache misses include metadata/b-tree/overflow work and are not a count of cold physical disk reads.", "", "| Dataset/query (SQLite cold) | Layout/mode | Requested | Copied | Extra slice copy | Metadata | Cache misses | Opens/reopens |", "| --- | --- | ---: | ---: | ---: | ---: | ---: | --- |"]
    for dataset in ["tsbs","alibaba"]:
        for case in ["point","sparse","full","summary"]:
            for v,m in columns:
                c=diagnostic(dataset,v,m,case,"cold")
                out.append(f"| {dataset}/{case} | {v}/{m} | {c['requested_body_bytes']:,} | {c['copied_blob_bytes']:,} | {c['extra_body_slice_copy_bytes']:,} | {c['copied_metadata_bytes']:,} | {c['sqlite_cache_misses']} | {c['blob_opens']}/{c['blob_reopens']} |")
    out += ["", "Separate `strace-*.txt` summaries count pread64 calls over process startup, fixture selection, eight warmups and one SQLite-cold query. They deliberately provide no speed numbers and do not isolate one query. They complement per-query SQLite misses; neither proves physical storage I/O. Incremental range access may still traverse overflow-chain pages even when it copies only one body.", "", "## Retention and lifecycle economics", "", "Each trace starts from a fresh copy, expires whole prefix blocks at 25/50/75/100% of the sealed time span, and clips overlapping blocks during comparison with original samples. Packs are never relocated/repacked. Directory live-mask publication, reference decrements and last-reference deletion share a FULL WAL transaction. A post-transaction census verifies every refcount/live-byte total and the absence of unreferenced packs; census time is excluded from maintenance diagnostics. Alternate-series retirement separately drops all sealed blocks in every second series, illustrating differing per-series lifetimes. Mutable heads stay present, so 100% here means all sealed blocks, not emptying the complete engine.", "", "| Dataset/layout/scenario | Live packs | Live bodies, B | Retained dead bodies, B | Payload b-tree, B | Freelist pages | WAL before checkpoint, B |", "| --- | ---: | ---: | ---: | ---: | ---: | ---: |"]
    for r in lifecycle:
        s=r["inspect"];p=s["packs"]or{};scenario=str(r["fraction"])+"%"if"fraction"in r else r["scenario"]
        out.append(f"| {r['dataset']}/{r['variant']}/{scenario} | {p.get('rows','—')} | {p.get('live_body_bytes','—')} | {p.get('dead_body_bytes','—')} | {owned(s,'payloads')+owned(s,'payload_packs'):,} | {s['freelist_pages']} | {r['wal_before_checkpoint_bytes']:,} |")
    out += ["", "File bytes and per-object pages after each checkpoint are in `lifecycle.jsonl`. Deleted/released pages join the freelist and do not shrink the file. Retained dead body bytes inside a live pack are different: they remain owned payload bytes and cannot be reused independently. No unmeasured repacking/compaction saving is assumed. Maintenance times are single-trace diagnostics, not stable speed claims; a production repacking design would need separate extra-I/O/WAL and atomic crash-publication measurements.", "", "## Environment and reproduction", "", f"Measured research base: `{env['research_commit']}`. Harness source, imported codec/exact modules, Cargo.lock, binary and official SQLite archive SHA256 hashes are preserved in `environment-density.json` and `environment-performance.json`. The user explicitly authorized exploratory uncommitted harness runs; these hashes pin the exact measured content. No production/submodule change is part of this round.", "", f"Environment: {env['cpuinfo']}; {env['uname']['system']} {env['uname']['machine']}; CPU affinity 0; cpu.max `{env['cpu_max']}`; memory.max `{env['memory_max']}`; {env['versions']['rustc']}; {env['versions']['go']}; {env['versions']['python']}. Stock rusqlite 0.40.1 links the matched static SQLite 3.53.4 archive and native zstd. `ldd` is preserved. WAL, synchronous=FULL, fullfsync/checkpoint_fullfsync, 4096-byte pages, 1 MiB cache, mmap=0 and query-only readers remain fixed. No other agent builds/tests/measurements ran during retained windows; host/storage activity remains outside the harness's control.", "", "Corpus inputs are public normalized TSBS and Alibaba from the common Go exporter, plus bounded synthetic regular/irregular/nonsparse/IEEE edge cases. Each copied manifest names exact corpus SHA256, sample and series counts and independently verified Go query hashes. Corpus/database files are fetched/generated and not committed.", "", "Reproduce from `<repo>/tinystore/metrics-payload-bench` using [the harness README](../metrics-payload-bench/README.md). The actual selected performance variants and fixed counts are in the raw plan. Every phase must run in an exclusive quiet window, and fixture files live on the Linux volume.", "", "Evidence: [density and per-object pages](data/metrics-payload-2026-10-09/density.jsonl), [all encoded byte replays](data/metrics-payload-2026-10-09/verification-bytes.jsonl), [full bitwise Go-manifest replays](data/metrics-payload-2026-10-09/verification.jsonl), [pilot and counts](data/metrics-payload-2026-10-09/plan.json), [six-pass summary](data/metrics-payload-2026-10-09/summary.json), [raw timings](data/metrics-payload-2026-10-09/timings.jsonl), [untimed cache diagnostics](data/metrics-payload-2026-10-09/diagnostics.jsonl), [retention traces](data/metrics-payload-2026-10-09/lifecycle.jsonl), [environment](data/metrics-payload-2026-10-09/environment-performance.json).", "", "## What follows", "", "Use the measured whole-file gain and retained-dead-byte cost together when judging a pack size. Incremental BLOB is a useful copy-control mechanism only after its open/reopen, metadata, cache-page and overflow-chain work is measured; copy bytes alone do not justify a performance or I/O claim. Production adoption would require hardening the experimental compact directory, exact query-budget accounting for both fetch modes, complete engine retention/head/clock integration, corruption/refcount recovery, crash/concurrency publication tests, reader pooling/cancellation, and a representative ongoing-ingest/maintenance WAL experiment. This prototype establishes none of those production guarantees.", ""]
    insertion=out.index("## Format, baseline and invariant checks")
    out[insertion:insertion]=["At 50% sealed-prefix expiry, TSBS compact-count8 retains 1,294,988 dead body bytes beside 1,299,371 live body bytes; Alibaba rowid-compact-count32 retains 1,303,151 dead beside 1,289,142 live bytes. These owned dead bytes are not reusable freelist pages, so fresh-file density alone does not establish retention-space savings.", ""]
    REPORT.write_text("\n".join(out))
    print(REPORT)


if __name__ == "__main__":
    main()
